-- Execute in BEGIN/ROLLBACK against Order System; no retained fixture or external send.
do $$ declare o uuid;n int;s jsonb;e uuid;first_seq bigint;cursor_value text;begin
 select auth_user_id into o from public.admin_users where role='owner' and is_active limit 1;
 if o is null then raise exception 'owner fixture missing';end if;
 if has_table_privilege('anon','public.icetak_mcp_tokens','SELECT') or has_table_privilege('authenticated','public.icetak_mcp_subscriptions','SELECT') or has_function_privilege('anon','public.icetak_mcp_claim_deliveries()','EXECUTE') then raise exception 'ACL leak';end if;
 insert into public.icetak_mcp_clients(client_id,redirect_uris) values('mcp-regression-client','["https://chatgpt.com/connector/oauth/regression"]');
 insert into public.icetak_mcp_codes(code_hash,client_id,owner_id,redirect_uri,challenge,scope,expires_at) values('mcp-regression-code','mcp-regression-client',o,'https://chatgpt.com/connector/oauth/regression','challenge','briefs:read',now()+interval '1 minute');
 select count(*) into n from public.icetak_mcp_consume_code('mcp-regression-code','mcp-regression-client','https://chatgpt.com/connector/oauth/regression','bad');if n<>0 then raise exception 'wrong PKCE accepted';end if;
 select count(*) into n from public.icetak_mcp_consume_code('mcp-regression-code','mcp-regression-client','https://chatgpt.com/connector/oauth/regression','challenge');if n<>1 then raise exception 'valid code rejected';end if;
 select count(*) into n from public.icetak_mcp_consume_code('mcp-regression-code','mcp-regression-client','https://chatgpt.com/connector/oauth/regression','challenge');if n<>0 then raise exception 'code replay accepted';end if;
 s:=jsonb_build_object('id','mcp-regression-sub','owner_id',o,'client_id','mcp-regression-client','order_reference','MCP_REGRESSION_ORDER','callback_url','https://chatgpt.com/mcp-events/regression','signing_secret','regression-only','expires_at',now()+interval '1 hour');
 perform public.icetak_mcp_subscribe(s,null);
 insert into public.clickup_order_brief_jobs(task_id,order_reference,state,brief,source_fingerprint) values('mcp_regression_task','MCP_REGRESSION_ORDER','review','{"confirmed":false}','regression-revision');
 if exists(select 1 from public.icetak_mcp_events where task_id='mcp_regression_task') then raise exception 'unconfirmed emitted';end if;
 update public.clickup_order_brief_jobs set state='completed',brief='{"confirmed":true}' where task_id='mcp_regression_task';
 select count(*) into n from public.icetak_mcp_events where task_id='mcp_regression_task';if n<>1 then raise exception 'confirmation not captured';end if;
 update public.clickup_order_brief_jobs set brief='{"confirmed":true,"unchanged":true}' where task_id='mcp_regression_task';
 select count(*) into n from public.icetak_mcp_events where task_id='mcp_regression_task';if n<>1 then raise exception 'duplicate event';end if;
 select count(*) into n from public.icetak_mcp_deliveries where subscription_id='mcp-regression-sub';if n<>1 then raise exception 'delivery missing';end if;
 insert into public.clickup_order_brief_jobs(task_id,order_reference,state,brief,source_fingerprint) values('mcp_regression_other','MCP_REGRESSION_OTHER','completed','{"confirmed":true}','regression-other');
 select count(*) into n from public.icetak_mcp_deliveries where subscription_id='mcp-regression-sub';if n<>1 then raise exception 'exact-order filter failed';end if;
 perform public.icetak_mcp_claim_deliveries();perform public.icetak_mcp_claim_deliveries();
 if not exists(select 1 from public.icetak_mcp_deliveries where subscription_id='mcp-regression-sub' and state='sending' and attempts=1) then raise exception 'lease replay failed';end if;
 s:=s||jsonb_build_object('id','mcp-regression-late');perform public.icetak_mcp_subscribe(s,null);
 if exists(select 1 from public.icetak_mcp_deliveries where subscription_id='mcp-regression-late') then raise exception 'first subscribe backfilled history';end if;
 perform public.icetak_mcp_subscribe(s,0);
 if not exists(select 1 from public.icetak_mcp_deliveries where subscription_id='mcp-regression-late') then raise exception 'cursor replay failed';end if;
 s:=s||jsonb_build_object('signing_secret','regression-rotated');perform public.icetak_mcp_subscribe(s,0);
 if not exists(select 1 from public.icetak_mcp_subscriptions where id='mcp-regression-late' and previous_signing_secret='regression-only' and rotation_until>now()) then raise exception 'signing rotation failed';end if;
 select seq into first_seq from public.icetak_mcp_events where task_id='mcp_regression_task';
 insert into public.icetak_mcp_events(task_id,order_reference,brief_revision,confirmed_at) values('mcp_regression_later','MCP_REGRESSION_ORDER','regression-later',now()) returning id into e;
 insert into public.icetak_mcp_deliveries(subscription_id,event_id) values('mcp-regression-late',e);
 select public.icetak_mcp_delivery_cursor('mcp-regression-late',e) into cursor_value;
 if cursor_value::bigint>=first_seq then raise exception 'cursor skipped pending event';end if;
 update public.icetak_mcp_subscriptions set active=false where id='mcp-regression-sub';perform public.icetak_mcp_claim_deliveries();
 if not exists(select 1 from public.icetak_mcp_deliveries where subscription_id='mcp-regression-sub' and state='stopped') then raise exception 'unsubscribe failed';end if;
 insert into public.icetak_mcp_tokens(access_hash,refresh_hash,client_id,owner_id,scope,expires_at,refresh_expires_at) values('mcp-regression-access','mcp-regression-refresh','mcp-regression-client',o,'briefs:read',now()+interval '1 hour',now()+interval '1 day');
 select count(*) into n from public.icetak_mcp_consume_refresh('mcp-regression-refresh','wrong');if n<>0 then raise exception 'wrong refresh client accepted';end if;
 select count(*) into n from public.icetak_mcp_consume_refresh('mcp-regression-refresh','mcp-regression-client');if n<>1 then raise exception 'refresh rejected';end if;
 select count(*) into n from public.icetak_mcp_consume_refresh('mcp-regression-refresh','mcp-regression-client');if n<>0 then raise exception 'refresh reused';end if;
end $$;
